   796	// detectReviewScope runs a handful of cheap `git` queries to describe the
   797	// set of changes the user is about to review. Best-effort: any individual
   798	// query that fails leaves the corresponding field at its zero value.
   799	func detectReviewScope(ctx context.Context) (reviewScope, error) {
   800		repoRoot, err := paths.WorktreeRoot(ctx)
   801		if err != nil {
   802			return reviewScope{}, fmt.Errorf("locate repo root: %w", err)
   803		}
   804		var s reviewScope
   805		s.Branch = gitString(ctx, repoRoot, "rev-parse", "--abbrev-ref", "HEAD")
   806		if s.Branch == detachedHEADDisplay {
   807			s.Branch = ""
   808		}
   809		s.HeadSHA = gitString(ctx, repoRoot, "rev-parse", "--short", "HEAD")
   810		base := detectBaseBranchRef(ctx, repoRoot)
   811		s.Base = base.display
   812		s.BaseRef = base.ref
   813		headRef := s.Branch
   814		if headRef == "" {
   815			headRef = "HEAD"
   816		}
   817		if s.BaseRef != "" && (s.Branch == "" || s.BaseRef != s.Branch) {
   818			if n, ok := gitCount(ctx, repoRoot, "rev-list", "--count", s.BaseRef+".."+headRef); ok {
   819				s.AheadCommits = n
   820			}
   821			if files := gitString(ctx, repoRoot, "diff", "--name-only", s.BaseRef+"..."+headRef); files != "" {
   822				s.FilesChanged = len(strings.Split(files, "\n"))
   823			}
   824		}
   825		if status := gitString(ctx, repoRoot, "status", "--porcelain"); status != "" {
   826			s.Uncommitted = len(strings.Split(status, "\n"))
   827		}
   828		return s, nil
   829	}
