   840	func detectBaseBranchRef(ctx context.Context, repoRoot string) baseBranchRef {
   841		if target := gitString(ctx, repoRoot, "symbolic-ref", "--short", "refs/remotes/origin/HEAD"); target != "" {
   842			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", target) {
   843				return baseBranchRef{display: strings.TrimPrefix(target, "origin/"), ref: target}
   844			}
   845		}
   846		candidates := []string{defaultBaseBranch, masterBaseBranch}
   847		for _, candidate := range candidates {
   848			ref := "origin/" + candidate
   849			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/remotes/"+ref) {
   850				return baseBranchRef{display: candidate, ref: ref}
   851			}
   852		}
   853		for _, candidate := range candidates {
   854			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/heads/"+candidate) {
   855				return baseBranchRef{display: candidate, ref: candidate}
   856			}
   857		}
   858		return baseBranchRef{}
   859	}
