   862	// "" on any error.
   863	func gitString(ctx context.Context, repoRoot string, args ...string) string {
   864		full := append([]string{"-C", repoRoot}, args...)
   865		out, err := exec.CommandContext(ctx, "git", full...).Output()
   866		if err != nil {
