   872	// gitOK runs `git -C repoRoot <args...>` and reports whether it succeeded.
   873	func gitOK(ctx context.Context, repoRoot string, args ...string) bool {
   874		full := append([]string{"-C", repoRoot}, args...)
   875		return exec.CommandContext(ctx, "git", full...).Run() == nil
   876	}
