   878	// gitCount runs a git command expected to output an integer and parses it.
   879	func gitCount(ctx context.Context, repoRoot string, args ...string) (int, bool) {
   880		s := gitString(ctx, repoRoot, args...)
   881		if s == "" {
   882			return 0, false
   883		}
   884		n, err := strconv.Atoi(s)
   885		if err != nil {
   886			return 0, false
   887		}
   888		return n, true
